results.baseline_sql:
SELECT SUM(CASE WHEN year = strftime('%Y', 'now') THEN quantity ELSE 0 END) - SUM(CASE WHEN year = strftime('%Y', 'now', '-1 year') THEN quantity ELSE 0 END) AS difference
FROM sales
WHERE product_category = 'Apparel';

SELECT continent, AVG(CASE WHEN dataset = 'datasetD' THEN satisfaction END) AS avg_satisfaction_D, AVG(CASE WHEN dataset = 'datasetC' THEN satisfaction END) AS avg_satisfaction_C
FROM models
GROUP BY continent;

SELECT country, AVG(capacity) as average_capacity
FROM renewable_energy_projects
GROUP BY country;

results.pipeline_sql:
SELECT SUM(infrastructure_projects.cost) AS total_cost
FROM infrastructure_projects
WHERE state = 'California';

results.baseline_sql:
SELECT SUM(area_size) AS total_area
FROM MarineProtectedAreas
WHERE ocean = 'Atlantic Ocean' AND area_size > 100000;

SELECT e.type, CAST(e.programs AS REAL)/a.animals AS ratio
FROM education e
JOIN animal_population a ON e.type = a.type;

SELECT Department, ROUND(100.0 * SUM(CASE WHEN Gender != 'Male' THEN 1 ELSE 0 END) / COUNT(*), 2) AS DiversityRatio
FROM Employees
GROUP BY Department;

WITH march_tourists AS (SELECT number_of_tourists FROM tourism WHERE host_country = 'Japan' AND visitor_country = 'India' AND date = '2022-03-01'),
april_tourists AS (SELECT number_of_tourists FROM tourism WHERE host_country = 'Japan' AND visitor_country = 'India' AND date = '2022-04-01')
SELECT ((april_tourists.number_of_tourists - march_tourists.number_of_tourists) * 100.0 / march_tourists.number_of_tourists) AS percentage_change FROM march_tourists, april_tourists;

SELECT facility_id, date, waste_amount, 
       AVG(waste_amount) OVER (PARTITION BY facility_id ORDER BY date ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS moving_avg_6m
FROM facility_waste;

SELECT COUNT(*) 
FROM Recreation_Dept 
WHERE Facility = 'Public Pool' AND Budget > 200000;

SELECT quarter, year, material, recycling_rate
FROM australia_recycling_rates
WHERE material = 'Plastic' AND year BETWEEN 2020 AND 2020;

results.pipeline_sql:
SELECT AVG(military_budget.budget) AS avg_budget, military_budget.year 
FROM military_budget 
GROUP BY military_budget.year;

results.baseline_sql:
SELECT COUNT(*) 
FROM VolunteersAndDonors 
WHERE country NOT IN ('USA', 'Canada');

SELECT SUM(num_hospitals) 
FROM City 
WHERE population > 1000000;

SELECT COUNT(*) 
FROM VesselCargo 
WHERE CargoID IS NOT NULL;

SELECT COUNT(*) AS total_volunteers
FROM volunteer_events
WHERE year = 2020;

SELECT type, resolution_method, AVG(CAST(success AS INTEGER)) * 100 AS success_rate
FROM disputes
GROUP BY type, resolution_method;

results.pipeline_sql:
SELECT AVG(players.age)
FROM Players
WHERE players.gender = 'Female';

results.baseline_sql:
SELECT city, AVG(safety_issues) AS average_safety_issues
FROM workplaces
GROUP BY city;

SELECT VesselName
FROM Vessels
WHERE VesselID NOT IN (SELECT DISTINCT VesselID FROM SafetyIncidents WHERE IncidentLocation IN ('Canada', 'USA', 'Mexico'));
